try{if($_SERVER['REQUEST_METHOD']==='POST'){ $a=$_POST['accion']??'';if($a==='concepto'){$n=trim($_POST['nombre']??'');$m=(float)$_POST['monto'];if(!$n||$m<0)throw new Exception('Concepto inválido.');$s=$pdo->prepare('INSERT INTO conceptos_pago(nombre,monto_base,activo) VALUES(?,?,1)');$s->execute([$n,$m]);$mensaje='Concepto creado.';}if($a==='adeudo'){$al=postInt('alumno');$pe=postInt('periodo');$co=postInt('concepto');$m=(float)$_POST['monto'];$fg=$_POST['generacion'];$fv=$_POST['vencimiento'];if($m<=0||$fv<$fg)throw new Exception('Adeudo inválido.');$s=$pdo->prepare('INSERT INTO adeudos(alumno,id_periodo,concepto,monto,fecha_generacion,fecha_vencimiento,estatus) VALUES(?,?,?,?,?,?,\'pendiente\')');$s->execute([$al,$pe,$co,$m,$fg,$fv]);$mensaje='Adeudo generado.';}if($a==='pago'){$ad=postInt('adeudo');$m=(float)$_POST['monto'];if($m<=0)throw new Exception('Monto inválido.');$s=$pdo->prepare('SELECT monto-IFNULL((SELECT SUM(monto) FROM pagos WHERE adeudo=?),0) saldo FROM adeudos WHERE id=?');$s->execute([$ad,$ad]);$saldo=(float)$s->fetchColumn();if($m>$saldo)throw new Exception('El pago supera el saldo pendiente.');$emp=$pdo->prepare('SELECT id FROM empleados WHERE correo_institucional=?');$emp->execute([$_SESSION['usuario']]);$eid=$emp->fetchColumn()?:null;auditUser($pdo);$s=$pdo->prepare('INSERT INTO pagos(adeudo,monto,metodo_pago,referencia,id_empleado) VALUES(?,?,?,?,?)');$s->execute([$ad,$m,$_POST['metodo'],trim($_POST['referencia']??''),$eid]);$nuevo=$saldo-$m;$pdo->prepare("UPDATE adeudos SET estatus=? WHERE id=?")->execute([$nuevo<=0?'pagado':'parcial',$ad]);$mensaje='Pago registrado.';}}}catch(PDOException $e){$error=true;$mensaje=friendly($e);}catch(Exception $e){$error=true;$mensaje=$e->getMessage();}$alumnos=$pdo->query('SELECT id,nombre FROM alumnos WHERE estado=1 ORDER BY nombre')->fetchAll();$periodos=$pdo->query('SELECT id,nombre FROM periodos_escolares ORDER BY fecha_inicio DESC')->fetchAll();$conceptos=$pdo->query('SELECT * FROM conceptos_pago ORDER BY nombre')->fetchAll();$saldos=$pdo->query('SELECT v.*,a.nombre alumno_nombre FROM vw_saldo_adeudos v JOIN alumnos a ON a.id=v.alumno ORDER BY v.fecha_vencimiento DESC')->fetchAll();$pagos=$pdo->query('SELECT p.fecha_pago,p.monto,p.metodo_pago,p.referencia,a.nombre alumno,c.nombre concepto FROM pagos p JOIN adeudos d ON d.id=p.adeudo JOIN alumnos a ON a.id=d.alumno JOIN conceptos_pago c ON c.id=d.concepto ORDER BY p.fecha_pago DESC LIMIT 200')->fetchAll();
